        map.put(StatIds.INC_CHANCE_TO_INFLICT_AILMENTS_WITH_PROJECTILES, self(StatEffectIds.EFF_ADD_VALUE_AILMENT_ATTRIBUTE_COE_AILMENT_CHANCE_PROJECTILE));
        // ── CHANCE_TO_*_ON_CRITICAL_HIT / _AGAINST_ENEMIES_THAT_ARE_NOT_POISONED 门控族（纯数据；复用既有 AILMENT_CHANCE EFF + COND_CRIT_HIT / 新增 COND_NOT_POISON_STATUS，零新增 EFF）──
