        map.put(StatIds.CHANCE_TO_INFLICT_BLEEDING_ON_CRITICAL_HIT_WITH_ATTACKS, self(StatConditionIds.COND_CRIT_HIT, StatEffectIds.EFF_ADD_VALUE_ATTRIBUTE_BLEED_COE_AILMENT_CHANCE));
        // CHANCE_TO_POISON_ON_HIT_DAMAGE_AGAINST_ENEMIES_THAT_ARE_NOT_POISONED → 对未中毒目标(onTarget)施加 POISON 异常几率（COND_NOT_POISON_STATUS 为 CompareValue 取反，live）。
        map.put(StatIds.CHANCE_TO_POISON_ON_HIT_DAMAGE_AGAINST_ENEMIES_THAT_ARE_NOT_POISONED, onTarget(StatConditionIds.COND_NOT_POISON_STATUS, StatEffectIds.EFF_ADD_VALUE_ATTRIBUTE_COE_AILMENT_CHANCE_POISON));
        // ── AGAINST_RARE_OR_UNIQUE 作用域 ailment chance（纯数据；复用 COND_PRESENCE_RARITY_RARE_UNIQUE + 既有 generic AILMENT_CHANCE EFF，零新增注册）──
        // INC_CHANCE_TO_INFLICT_AILMENTS_AGAINST_RARE_OR_UNIQUE_ENEMIES → onTarget 求值（目标侧稀有/传奇），同构 INC_CHANCE_TO_INFLICT_AILMENTS 的 EFF。
        map.put(StatIds.INC_CHANCE_TO_INFLICT_AILMENTS_AGAINST_RARE_OR_UNIQUE_ENEMIES, onTarget(StatConditionIds.COND_PRESENCE_RARITY_RARE_UNIQUE, StatEffectIds.EFF_ADD_VALUE_AILMENT_ATTRIBUTE_COE_AILMENT_CHANCE));
        // ── ANY_EXPOSURE 聚合（纯数据；AnyValue OR 节点 → COND_ANY_EXPOSURE，复用既有 generic EFF，零新属性）──
