        map.put(StatIds.INC_CHANCE_TO_INFLICT_AILMENTS_AGAINST_ENEMIES_WITH_EXPOSURE, onTarget(StatConditionIds.COND_ANY_EXPOSURE, StatEffectIds.EFF_ADD_VALUE_AILMENT_ATTRIBUTE_COE_AILMENT_CHANCE));
