        map.put(StatIds.INC_SPELL_DAMAGE_WHILE_YOU_HAVE_ARCANE_SURGE, self(StatConditionIds.COND_ARCANE_SURGE_STATUS, StatEffectIds.EFF_ADD_MULTIPLIED_BASE_ATTRIBUTE_COE_DAMAGE_DAMAGE_SPELL));
